mapper.select:
select * from (
select 'request' as doc_type, request_id as doc_id, request_no as doc_no, title, null as supplier_name, status, total_amount as amount, null as paid_amount, expect_date as doc_date, plan_no as rel_no, create_time from pms_purchase_request where del_flag = '0' and source_project_id = #{projectId}
and request_no like concat('%', #{docNo}, '%')
and status = #{status}
union all select 'plan' as doc_type, plan_id as doc_id, plan_no as doc_no, title, null as supplier_name, status, budget_amount as amount, actual_amount as paid_amount, start_date as doc_date, null as rel_no, create_time from pms_purchase_plan where del_flag = '0' and source_project_id = #{projectId}
and plan_no like concat('%', #{docNo}, '%')
and status = #{status}
union all select 'order' as doc_type, order_id as doc_id, order_no as doc_no, concat('采购订单 - ', ifnull(supplier_name, '')) as title, supplier_name, status, total_amount as amount, paid_amount, order_date as doc_date, request_no as rel_no, create_time from pms_purchase_order where del_flag = '0' and source_project_id = #{projectId}
and order_no like concat('%', #{docNo}, '%')
and status = #{status}
union all select 'contract' as doc_type, contract_id as doc_id, contract_no as doc_no, contract_name as title, supplier_name, status, contract_amount as amount, paid_amount, sign_date as doc_date, order_no as rel_no, create_time from pms_contract where del_flag = '0' and source_project_id = #{projectId}
and contract_no like concat('%', #{docNo}, '%')
and status = #{status}
) t order by t.create_time desc
